const printQty=(s,portions=1)=>{let n=qtyNumber(s);return Number.isFinite(n)?String(Math.round(n*portions*1000)/1000).replace('.',','):h(s)};
const formatDate=s=>s?new Date(s).toLocaleDateString('de-DE'):'–';
const newCocktail=()=>({id:id(),name:'',category:'',image:'',glass:'',bases:[],methods:[],primaryMethod:'',ingredients:[],garnishes:[],steps:[{id:id(),text:''}],taste:{},tasteScale:TASTE_MAX,notes:'',favorite:false,draft:true,createdAt:now(),updatedAt:now()});
const newIngredient=()=>({id:id(),name:'',category:'',image:'',available:false,notes:'',substitutes:[],createdAt:now(),updatedAt:now()});
const newUI=()=>({sort:'name',display:'grid',quickMix:false,quickFav:false,search:'',searchOpen:false,advanced:{categories:[],bases:[],ingredients:[],ingredientMode:'and',includeSubs:true,includeGarnishes:false},barSearch:'',stockFilter:'all',barOpened:[],settingsOpened:['Daten & Sicherung'],daily:{day:'',id:'',excluded:[]},cardIds:[],cardOrder:[],backupDate:'',backupSnooze:'',firstRunDate:now(),cardName:'Unsere Cocktailkarte',firebase:{projectId:'',apiKey:'',email:'',uid:'',refreshToken:'',cardId:'',publishedIds:[]}});
let state={cocktails:[],ingredients:[],pending:{},ui:newUI()},route={type:'main',tab:'home'},history=[],editor=null,editorDirty=false,validationErrors=[],picker=null,modal=null,toastTimer=null,detailSession={servings:1,subs:{},amounts:{}},ingredientEditing=false,photoTarget=null,crop=null,saving=false;
let db=null,saveTimer=null,online=navigator.onLine,installPrompt=null;
