function openDB(){return new Promise((res,rej)=>{let req=indexedDB.open('cocktails-app-data',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}
function readDB(){return new Promise((res,rej)=>{let req=db.transaction('data','readonly').objectStore('data').get('state');req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}
function writeDB(){return new Promise((res,rej)=>{let req=db.transaction('data','readwrite').objectStore('data').put(state,'state');req.onsuccess=()=>res();req.onerror=()=>rej(req.error)})}
function queueSave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveNow(),300)}
async function saveNow(){clearTimeout(saveTimer);if(saving){queueSave();return}saving=true;try{await writeDB();let status=$('#save-state');if(status)status.innerHTML=`${ico('checkcircle')} Entwurf lokal gesichert`}catch(e){console.error(e);let status=$('#save-state');if(status){status.style.color='#f19b9b';status.textContent='Lokale Sicherung fehlgeschlagen'}showToast('Speichern fehlgeschlagen. Speicherplatz prüfen.')}finally{saving=false}}
function ensureUI(){state.ui={...newUI(),...state.ui};state.ui.advanced={...newUI().advanced,...state.ui.advanced};state.ui.firebase={...newUI().firebase,...state.ui.firebase};state.pending=state.pending||{};state.cocktails=state.cocktails||[];state.ingredients=state.ingredients||[]}
// Einmalige Datenmigration: alte 10er-Geschmackswerte in fünf Stufen überführen.
// 1/2→1, 3/4→2, 5/6→3, 7/8→4, 9/10→5. Unbewertet bleibt unbewertet.
function upgradeTasteData(){
  let changed=false;
  const convert=c=>{
    if(!c||c.tasteScale===TASTE_MAX)return;
    if(!c.taste||typeof c.taste!=='object')c.taste={};
    for(const [key] of TASTES){
      if(c.taste[key]===undefined||c.taste[key]===null||c.taste[key]==='')continue;
      const value=Number(c.taste[key]);
      if(!Number.isFinite(value)||value<=0)delete c.taste[key];
      else c.taste[key]=Math.min(TASTE_MAX,Math.max(1,Math.ceil(value/2)));
    }
    c.tasteScale=TASTE_MAX;
    changed=true;
  };
  for(const c of state.cocktails)convert(c);
  for(const c of Object.values(state.pending||{}))convert(c);
  return changed;
}
function showToast(text,action=null){let old=$('.toast');old?.remove();let d=document.createElement('div');d.className='toast';d.innerHTML=`<span>${h(text)}</span>${action?`<button id="toast-undo">Rückgängig</button>`:''}`;document.body.append(d);if(action)d.querySelector('button').onclick=()=>{action();d.remove()};clearTimeout(toastTimer);toastTimer=setTimeout(()=>d.remove(),4500)}
