const nav=()=>`<nav class="bottom-nav" aria-label="Hauptnavigation"><div class="nav-inner">${[['home','home','Start'],['cocktails','martini','Cocktails'],['bar','bar','Meine Bar'],['settings','settings','Einstellungen']].map(([tab,icon,label])=>`<button class="nav-item ${route.tab===tab?'selected':''}" data-act="nav" data-tab="${tab}">${ico(icon)}<span>${label}</span></button>`).join('')}</div></nav>`;
const footer=(text,action,label)=>`<footer class="editor-footer"><div class="save-state" id="save-state">${ico('checkcircle')} ${h(text)}</div><button class="btn primary wide" data-act="${action}">${h(label)}</button></footer>`;
const photo=(data,name,color='#D6C4A1',extra='')=>`<div class="photo ${extra}" style="--accent:${color}">${data?`<img loading="lazy" src="${h(data)}" alt="${h(name)}">`:`<span class="monogram">${h((name||'?').trim().substring(0,2)||'?')}</span>`}</div>`;
const statusFor=c=>{let substitutes=false,missing=false;for(const entry of c.ingredients||[]){let ing=ingredient(entry.ingredientId);if(!ing){missing=true;continue}if(ing.available)continue;if((ing.substitutes||[]).some(sid=>ingredient(sid)?.available))substitutes=true;else missing=true}return missing?'bad':substitutes?'warn':'good'};
const statusText=(s)=>s==='good'?'Direkt mixbar':s==='warn'?'Mit Ersatz mixbar':'Nicht mixbar';
const statusIcon=s=>`<span class="status ${s}">${ico(s==='bad'?'warning':'checkcircle')} ${statusText(s)}</span>`;
function filteredCocktails(){let u=state.ui,a=u.advanced,list=state.cocktails.filter(c=>!c.draft);if(u.search.trim()){let q=u.search.toLocaleLowerCase('de');list=list.filter(c=>[c.name,...(c.bases||[])].some(s=>s.toLocaleLowerCase('de').includes(q)))}if(u.quickFav)list=list.filter(c=>c.favorite);if(u.quickMix)list=list.filter(c=>statusFor(c)!=='bad');if(a.categories.length)list=list.filter(c=>a.categories.includes(c.category));if(a.bases.length)list=list.filter(c=>c.bases.some(b=>a.bases.includes(b)));
if(a.ingredients.length){list=list.filter(c=>{let all=[...(c.ingredients||[]),...(a.includeGarnishes?c.garnishes||[]:[])];let has=selectedId=>all.some(en=>{if(en.ingredientId===selectedId)return true;if(!a.includeSubs)return false;let orig=ingredient(en.ingredientId);return !!orig?.substitutes?.includes(selectedId)});return a.ingredientMode==='and'?a.ingredients.every(has):a.ingredients.some(has)})}
const cmp=(a,b)=>a.name.localeCompare(b.name,'de');let sort=u.sort;list.sort((a,b)=>{if(sort==='nameDesc')return -cmp(a,b);if(sort==='category')return CATS.findIndex(c=>c[0]===a.category)-CATS.findIndex(c=>c[0]===b.category)||cmp(a,b);if(sort==='mix')return ['good','warn','bad'].indexOf(statusFor(a))-['good','warn','bad'].indexOf(statusFor(b))||cmp(a,b);if(sort==='new')return b.createdAt.localeCompare(a.createdAt);if(sort==='edited')return b.updatedAt.localeCompare(a.updatedAt);if(sort.startsWith('taste-')){let parts=sort.split('-'),key=parts[1],ascending=parts[2]==='asc',av=a.taste[key],bv=b.taste[key];if(!av&&!bv)return cmp(a,b);if(!av)return 1;if(!bv)return -1;return (ascending?av-bv:bv-av)||cmp(a,b)}return cmp(a,b)});return list}
function navTo(next,replace=false){if(!replace)history.push({route:clone(route),y:window.scrollY});route=next;render();window.scrollTo(0,0)}
function goBack(){if(modal){modal=null;render();return}if(route.type==='editCocktail'||route.type==='editIngredient'){if(editorDirty){modal={type:'leave-edit'};render();return}editor=null}if(route.type==='picker'){if(picker?.dirty){modal={type:'leave-picker'};render();return}picker=null}if(route.type==='subPick'){saveSubChoices(false)}let last=history.pop();if(last){route=last.route;render();requestAnimationFrame(()=>window.scrollTo(0,last.y||0))}else{route={type:'main',tab:'home'};render();window.scrollTo(0,0)}}
