let editorSections=new Set([0]),activePickerTab='ingredients',pickerSearch='',pickerCategory='Alle Kategorien',barSearch='',filterIngredientSearch='',sortSheet=false,zoomSession={z:1,x:0,y:0};
function fullCard(c,listing=false){let color=accent(c.category),status=statusFor(c);return `<article class="drink-card" style="--accent:${color}"><div class="card-top" data-act="open-cocktail" data-id="${c.id}" role="button" tabindex="0">${photo(c.image,c.name,color)}</div><div class="drink-card-content" data-act="open-cocktail" data-id="${c.id}"><h3>${h(c.name)}</h3><div class="status ${status}">${ico(status==='bad'?'warning':'checkcircle')} ${statusText(status)}</div></div><button class="card-heart" data-act="favorite" data-id="${c.id}" aria-label="Favorit" title="Favorit">${ico('heart')}<span class="hide">${c.favorite?'Favorit':'Kein Favorit'}</span></button></article>`}
